-- Workspaces seeded before the Test with AI play existed get it here; new workspaces get it from SeedDefaults.
INSERT INTO plays (id, workspace_id, label, type, description, instructions, enabled, show_when_stage, excluded_project_ids, created_by, created_at, updated_at)
SELECT lower(hex(randomblob(16))), w.id, 'Test with AI', 'ticket', 'Tests the ticket on its test environment against its acceptance criteria, then passes or fails it.', 'Test this ticket the way a tester would, then pass or fail it. Read it with `ticket_get` and its links with `ticket_get_links`; its acceptance criteria are what you test against. Follow the testing strategy in this project''s interview memory, which comes with this run. With no interview, check each criterion on the live URL and run the tests the project already has, and add none. Get where to test with `ticket_get_test_target`. Test nowhere else: never production, and never anything that shares production''s services. If its url is empty, the only place to test is production: stop without passing or failing the ticket, and reply that it needs a deploy branch on its own network. Open the url and check it against each acceptance criterion in turn, noting what you did and what you saw. Run the project''s tests. List its repositories with `project_list_repos`: when one has the role tests, run them from that repository, cloning it if the checkout you are running in is not it; otherwise run them in this checkout on the ticket''s linked branch. Where the interview calls for an automated end-to-end suite, add or extend a test covering the ticket''s acceptance criteria, run it against the url, commit it, and push: to the ticket''s linked branch, or in a tests repository to a branch named `<ticket key>-<short-slug>` with a pull request whose title starts with the ticket key. Then record the result exactly as a person would. If every criterion holds and the tests pass, call `ticket_test_pass`. Otherwise call `ticket_test_fail` with the bug template filled: the steps to reproduce, the expected result the criterion promises, and the actual result you saw. It posts them to the ticket''s thread and moves the ticket back to progress. Reply with each criterion and whether it held, the tests you ran and added, and the result you recorded. If you cannot reach the url or run the tests, say what blocked you instead of passing or failing the ticket.', 1, 'testing', '[]', '', strftime('%s','now'), strftime('%s','now')
FROM workspaces w
WHERE NOT EXISTS (SELECT 1 FROM plays p WHERE p.workspace_id = w.id AND p.label = 'Test with AI');
